func trGroup(data *port.Cells, stride int32, col int32, n int32, nc int32, idx *port.Cells, off *port.Cells) int32 {
	// Counting sort of `n` records of `data` (cells per record `stride`, component id at `col`, -1 skipped) by component:
	// `off` gets nc + 1 offsets, `idx` the record numbers grouped by component in record order. Answers the count grouped.
	var i int32 = 0
	var c int32 = 0
	var acc int32 = 0
	var v int32 = 0
	port.CellsDrop(off, 0)
	port.CellsGrow(off, nc+1, 0)
	for i < n {
		c = port.CellsAt(data, (i*stride)+col)
		if c >= 0 {
			v = port.CellsAt(off, c+1)
			port.CellsSet(off, c+1, v+1)
		}
		i += 1
	}
	c = 0
	for c < nc {
		v = port.CellsAt(off, c+1)
		acc += v
		port.CellsSet(off, c+1, acc)
		c += 1
	}
	port.CellsDrop(idx, 0)
	port.CellsGrow(idx, acc, 0)
	// fill: the offsets are cursors, then shifted back
	i = 0
	for i < n {
		c = port.CellsAt(data, (i*stride)+col)
		if c >= 0 {
			v = port.CellsAt(off, c)
			port.CellsSet(idx, v, i)
			port.CellsSet(off, c, v+1)
		}
		i += 1
	}
	c = nc
	for c > 0 {
		port.CellsSet(off, c, port.CellsAt(off, c-1))
		c -= 1
	}
	port.CellsSet(off, 0, 0)
	return acc
}

